// domínio
class Pedido {
  constructor(itens, cliente) {
    this.itens = itens;
    this.cliente = cliente;
  }

  total() {
    return this.itens.reduce((s, item) => s + item.preco, 0);
  }
}

class CalcularValorPedido {
  executar(pedido) {
    if (pedido.total() <= 0) {
      throw new Error('Pedido sem itens válidos');
    }
    return pedido.total();
  }
}

